import { useEffect, useRef, useState, type ReactNode } from 'react';
import { Activity, Bot, ChevronDown, Clock3, GripVertical, Headphones, Heart, History, Home, Info, ListMusic, LogOut, Mic2, Music2, Pause, Pin, Play, Plus, Radio, Repeat2, RotateCcw, Search, Settings, SkipBack, SkipForward, Square, Trash2, Volume2, Wifi, Zap } from 'lucide-react';
import type { BotEvent, Command, Config, Library, PlayerState, Playlist, Track } from './types';
import { loadYouTubeIframeApi, YOUTUBE_CLIENT_IDENTITY, youtubePlaybackError, type YouTubePlayer } from './youtube-player';
import inazumaLogo from '../assets/inazuma-raimon.png';

const initialState: PlayerState = { connected:false, botOnline:false, latencyMs:0, discordClientId:'', userName:'', userAvatar:'', guildId:'', guildName:'Aucun serveur', guilds:[], textChannels:[], voiceChannel:'Aucun salon', voiceMembers:[], playing:false, volume:64, loop:'off', audioPreset:'normal', normalizeVolume:true, crossfadeSeconds:3, position:0, elapsed:0, current:null, queue:[], history:[] };
const tabs = [{id:'home',label:'Accueil',icon:Home},{id:'search',label:'Recherche',icon:Search},{id:'lyrics',label:'Paroles',icon:Mic2},{id:'favorites',label:'Favoris',icon:Heart},{id:'playlists',label:'Playlists',icon:Music2},{id:'queue',label:'Queue',icon:ListMusic},{id:'history',label:'Historique',icon:History},{id:'settings',label:'Paramètres',icon:Settings}];
const navTabs=tabs.filter(tab=>tab.id!=='settings');
const rid=()=>Math.random().toString(36).slice(2);
let enqueueTrackRow:((track:Track)=>void)|null=null;
function decode(s:string){ const t=document.createElement('textarea');t.innerHTML=s;return t.value }
function isoDuration(s:string){ if(!s.startsWith('P')) return s; const m=s.match(/PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/); if(!m)return s; const h=Number(m[1]||0),n=Number(m[2]||0),x=Number(m[3]||0); return `${h?`${h}:`:''}${String(n).padStart(h?2:1,'0')}:${String(x).padStart(2,'0')}` }
function seconds(s:string){if(!s||s==='LIVE')return 0;const p=s.split(':').map(Number);return p.some(Number.isNaN)?0:p.reduce((a,b)=>a*60+b,0)}

export default function App(){
  const [tab,setTab]=useState('home'); const [config,setConfig]=useState<Config|null>(null); const [state,setState]=useState(initialState);
  const [localState,setLocalState]=useState({...initialState,connected:true,botOnline:true,voiceChannel:'Lecture dans l’application'});
  const [library,setLibrary]=useState<Library>({history:[],playlists:[],favorites:[],pinned:[],searchHistory:[],stats:{totalSeconds:0,tracksPlayed:0,playCount:{},lastPlayedAt:0}}); const previousTrack=useRef<Track|null>(null); const previousElapsed=useRef(0);
  const [notice,setNotice]=useState(''); const [logs,setLogs]=useState(''); const socket=useRef<WebSocket|null>(null); const reconnect=useRef<number>();
  const radioBusy=useRef(false);
  const radioRecommendations=useRef<{seedId:string;tracks:Track[];loading:Promise<Track[]>|null}>({seedId:'',tracks:[],loading:null});
  const demo=config?.demoMode;
  const local=config?.playbackTarget==='local';
  const activeState=local?{...state,playing:localState.playing,volume:localState.volume,loop:localState.loop,position:localState.position,elapsed:localState.elapsed,current:localState.current,queue:localState.queue,history:localState.history,voiceChannel:'Lecture dans l’application',voiceMembers:[]}:state;
  const connect=()=>{ if(!config||config.demoMode)return; window.clearTimeout(reconnect.current); socket.current?.close(); try{
    const ws=new WebSocket(config.wsUrl); socket.current=ws;
    ws.onopen=()=>{ const context={discordUserId:config.discordUserId,preferredGuildId:config.preferredGuildId,preferredTextChannelId:config.preferredTextChannelId,autoJoin:config.autoJoin,autoLeave:config.autoLeave,controlMode:config.controlMode,allowedRoleIds:config.allowedRoleIds,audioPreset:config.audioPreset,normalizeVolume:config.normalizeVolume,crossfadeSeconds:config.crossfadeSeconds}; setState(s=>({...s,connected:true})); ws.send(JSON.stringify({type:'auth',token:config.apiToken})); ws.send(JSON.stringify({type:'command',action:'get_state',requestId:rid(),context})); };
    ws.onmessage=e=>{ try{ const msg:BotEvent=JSON.parse(e.data); if(msg.type==='state')setState(s=>({...s,...msg.payload,connected:true})); else if(msg.type==='event'){const result=msg.payload as {ok?:boolean;message?:string};if(result?.ok===false)setNotice(result.message||'Commande refusée par le bot.')}}catch{} };
    ws.onclose=()=>{setState(s=>({...s,connected:false,botOnline:false}));reconnect.current=window.setTimeout(connect,3000)};
  }catch(e){setNotice(String(e))} };
  useEffect(()=>{window.newaa.getConfig().then(c=>{setConfig(c);if(c.demoMode)setState({...initialState,connected:true,botOnline:true,guildName:'Mode démonstration',voiceChannel:'Aucun salon',playing:false,current:null,queue:[],history:[]})});window.newaa.getLibrary().then(setLibrary);const offLog=window.newaa.onBotLog(x=>setLogs(v=>(v+x).slice(-12000)));const offUpdate=window.newaa.onUpdate(x=>{if(x.state==='downloading')setNotice(`Mise à jour ${x.version} en téléchargement…`);if(x.state==='progress')setNotice(`Téléchargement de la mise à jour : ${x.percent}%`);if(x.state==='ready')setNotice(`Mise à jour ${x.version} prête, redémarrage…`)});return()=>{offLog();offUpdate()}},[]);
  useEffect(()=>{if(config)document.documentElement.dataset.theme=config.theme},[config?.theme]);
  useEffect(()=>{if(!config||config.discordClientId||!/^[0-9]{17,20}$/.test(state.discordClientId))return;const next={...config,discordClientId:state.discordClientId};window.newaa.setConfig(next).then(setConfig).catch(()=>{})},[config?.discordClientId,state.discordClientId]);
  useEffect(()=>{const current=activeState.current;if(previousTrack.current&&previousTrack.current.id!==current?.id){const old=previousTrack.current;setLibrary(l=>{const listened=Math.max(0,previousElapsed.current);const next={...l,history:[old,...l.history.filter(x=>x.id!==old.id)].slice(0,200),stats:{...l.stats,totalSeconds:l.stats.totalSeconds+listened,tracksPlayed:l.stats.tracksPlayed+1,playCount:{...l.stats.playCount,[old.id]:(l.stats.playCount[old.id]||0)+1},lastPlayedAt:Date.now()}};window.newaa.saveLibrary(next);return next})}previousTrack.current=current},[activeState.current?.id]);
  const saveLibrary=(next:Library)=>{setLibrary(next);window.newaa.saveLibrary(next)};
  useEffect(()=>{previousElapsed.current=activeState.elapsed},[activeState.elapsed]);
  const addToPlaylist=(playlistId:string,track:Track)=>{const playlists=library.playlists.map(p=>p.id===playlistId?{...p,tracks:[...p.tracks.filter(x=>x.id!==track.id),track]}:p);const next={...library,playlists};saveLibrary(next);const updated=playlists.find(p=>p.id===playlistId);if(updated?.visibility==='public')window.newaa.publishPlaylist(updated).catch(e=>setNotice(e instanceof Error?e.message:String(e)));setNotice('Ajouté à la playlist.')} ;
  useEffect(()=>{if(config)connect(); return()=>{window.clearTimeout(reconnect.current);socket.current?.close()}},[config?.wsUrl,config?.apiToken,config?.demoMode]);
  useEffect(()=>{if(!notice)return;const t=setTimeout(()=>setNotice(''),3000);return()=>clearTimeout(t)},[notice]);
  useEffect(()=>{if(local||!state.playing||!state.current)return;const timer=window.setInterval(()=>setState(s=>{if(!s.playing||!s.current)return s;const elapsed=s.elapsed+1,total=seconds(s.current.duration);return{...s,elapsed,position:total?Math.min(100,elapsed/total*100):0}}),1000);return()=>window.clearInterval(timer)},[state.playing,state.current?.id,local]);
  useEffect(()=>{const seed=localState.current;if(!local||!config?.autoRadio||!seed||seed.source==='mp3'||localState.queue.length)return;const cleanTitle=seed.title.replace(/[\[(].*?[\])]/g,' ').replace(/\b(official|clip|video|audio|lyrics?|paroles|hd|4k)\b/gi,' ').replace(/\s+/g,' ').trim();const loading=window.newaa.searchYouTube(`${seed.channel} ${cleanTitle} musique similaire`).then(result=>result.items.map(track=>({...track,title:decode(track.title),channel:decode(track.channel),duration:isoDuration(track.duration),source:'youtube' as const}))).catch(()=>[]);radioRecommendations.current={seedId:seed.id,tracks:[],loading};loading.then(tracks=>{if(radioRecommendations.current.seedId===seed.id)radioRecommendations.current={seedId:seed.id,tracks,loading:null}})},[local,config?.autoRadio,localState.current?.id,localState.queue.length]);
  const send=(action:string,payload?:unknown)=>{
    if(action==='previous'){const previous=library.history.find(track=>track.id!==activeState.current?.id);if(previous)send('play_now',previous);else setNotice('Aucun morceau précédent dans l’historique.');return}
    if(local&&['play_now','play_next','enqueue','toggle_pause','skip','ended','stop','volume','loop','seek','remove_queue','clear_queue','reorder_queue'].includes(action)){window.dispatchEvent(new CustomEvent('inazuma-local-command',{detail:{action,payload}}));if((action==='ended'||action==='skip')&&localState.current&&!localState.queue.length&&localState.loop==='off'&&config?.autoRadio){void continueLocalWithRadio(action);return}localCommand(action,payload);return}
    if(demo){ demoCommand(action,payload); return }
    if(socket.current?.readyState!==WebSocket.OPEN){setNotice('Le bot n’est pas connecté.');return}
    const context={discordUserId:config?.discordUserId||'',preferredGuildId:config?.preferredGuildId||'',preferredTextChannelId:config?.preferredTextChannelId||'',autoJoin:config?.autoJoin??true,autoLeave:config?.autoLeave??true,controlMode:config?.controlMode||'private',allowedRoleIds:config?.allowedRoleIds||'',audioPreset:config?.audioPreset||'normal',normalizeVolume:config?.normalizeVolume??true,crossfadeSeconds:config?.crossfadeSeconds??3};
    const message:Command={type:'command',action,payload,requestId:rid(),context};socket.current.send(JSON.stringify(message));
  };
  const localCommand=(action:string,payload?:unknown)=>setLocalState(s=>{
    if(action==='toggle_pause')return{...s,playing:!!s.current&&!s.playing};if(action==='volume')return{...s,volume:Number(payload)};if(action==='loop')return{...s,loop:['off','track','queue'].includes(String(payload))?payload as PlayerState['loop']:'off'};if(action==='seek'){const elapsed=Math.max(0,Number(payload)||0),total=seconds(s.current?.duration||'');return{...s,elapsed,position:total?Math.min(100,elapsed/total*100):0}};
    if(action==='stop')return{...s,playing:false,current:null,queue:[],elapsed:0,position:0};if(action==='skip'){const[next,...rest]=s.queue;return{...s,current:next||null,queue:rest,history:s.current?[s.current,...s.history]:s.history,playing:!!next,elapsed:0,position:0}}
    if(action==='ended'){if(s.loop==='track')return{...s,playing:true,elapsed:0,position:0};const[next,...rest]=s.queue;if(s.loop==='queue'&&s.current){const upcoming=next||s.current;return{...s,current:upcoming,queue:next?[...rest,s.current]:[],history:[s.current,...s.history],playing:true,elapsed:0,position:0}}return{...s,current:next||null,queue:rest,history:s.current?[s.current,...s.history]:s.history,playing:!!next,elapsed:0,position:0}}
    if(action==='play_now'){const t=payload as Track;return{...s,current:t,queue:[],playing:true,history:s.current?[s.current,...s.history]:s.history,elapsed:0,position:0}}
    if(action==='play_next'){const t=payload as Track;return{...s,queue:s.current?[t,...s.queue]:s.queue,current:s.current||t,playing:true,elapsed:s.current?s.elapsed:0,position:s.current?s.position:0}}
    if(action==='enqueue'){const t=payload as Track;return s.current?{...s,queue:[...s.queue,t]}:{...s,current:t,playing:true,elapsed:0,position:0}}
    if(action==='remove_queue')return{...s,queue:s.queue.filter((_,i)=>i!==Number(payload))};if(action==='clear_queue')return{...s,queue:[]};if(action==='reorder_queue')return{...s,queue:payload as Track[]};return s;
  });
  async function continueLocalWithRadio(action:'ended'|'skip'){
    if(radioBusy.current)return;
    const seed=localState.current;if(!seed)return;
    radioBusy.current=true;localCommand(action);setNotice('Radio Inazuma : prochain morceau…');
    try{
      const excluded=new Set([seed.id,...localState.history.slice(0,20).map(track=>track.id),...library.history.slice(0,20).map(track=>track.id)]);
      const cached=radioRecommendations.current.seedId===seed.id?radioRecommendations.current:null;
      const remote=cached?.tracks.length?cached.tracks:cached?.loading?await Promise.race([cached.loading,new Promise<Track[]>(resolve=>setTimeout(()=>resolve([]),3500))]):[];
      const fallback=[...library.favorites,...library.pinned,...library.history,...localState.history];
      const next=remote.find(track=>!excluded.has(track.id))||fallback.find(track=>track.id!==seed.id)||seed;
      localCommand('play_now',next);setNotice(`Radio Inazuma : ${next.title}`);
    }catch{localCommand('play_now',seed);setNotice('Radio Inazuma : reprise du morceau.')}finally{radioBusy.current=false}
  }
  const syncLocalProgress=(elapsed:number,duration:number)=>setLocalState(s=>{if(!s.current)return s;const safeElapsed=Math.max(0,elapsed||0),safeDuration=Math.max(0,duration||seconds(s.current.duration));return{...s,elapsed:safeElapsed,position:safeDuration?Math.min(100,safeElapsed/safeDuration*100):0}});
  const setLocalPlayback=(playing:boolean)=>setLocalState(s=>s.current?{...s,playing}:s);
  const failLocalPlayback=(message:string)=>{setLocalState(s=>s.current?{...s,playing:false}:s);setNotice(message)};
  const changeOutput=async(playbackTarget:'local'|'discord')=>{if(playbackTarget===config?.playbackTarget)return;if(playbackTarget==='local'&&state.current)send('stop');if(playbackTarget==='discord'&&localState.current){window.dispatchEvent(new CustomEvent('inazuma-local-command',{detail:{action:'stop'}}));localCommand('stop')}if(config)setConfig(await window.newaa.setConfig({...config,playbackTarget}))};
  useEffect(()=>window.newaa.onMediaCommand(action=>send(action)),[config?.wsUrl,config?.discordUserId,demo,local,library.history,activeState.current?.id]);
  useEffect(()=>{if(activeState.current)window.newaa.notifyTrack(activeState.current)},[activeState.current?.id]);
  useEffect(()=>{window.newaa.updatePresence(activeState.current,activeState.playing).catch(()=>{})},[activeState.current?.id,activeState.playing]);
  const demoCommand=(action:string,payload?:unknown)=>setState(s=>{
    if(action==='toggle_pause')return{...s,playing:!s.playing}; if(action==='volume')return{...s,volume:Number(payload)};
    if(action==='stop')return{...s,playing:false,current:null,queue:[]}; if(action==='skip'){const [next,...rest]=s.queue;return{...s,current:next||null,queue:rest,history:s.current?[s.current,...s.history]:s.history,playing:!!next}}
    if(action==='play_now'){const t=payload as Track;return{...s,current:t,playing:true,history:s.current?[s.current,...s.history]:s.history}}
    if(action==='enqueue'){return{...s,queue:[...s.queue,payload as Track]}} if(action==='play_next'){return{...s,queue:[payload as Track,...s.queue]}}
    if(action==='remove_queue'){return{...s,queue:s.queue.filter((_,i)=>i!==Number(payload))}} if(action==='clear_queue')return{...s,queue:[]}; if(action==='reorder_queue')return{...s,queue:payload as Track[]}; return s;
  });
  enqueueTrackRow=track=>send('enqueue',track);
  if(!config)return <div className="loading"><Music2/> Chargement d’Inazuma Music…</div>;
  if(new URLSearchParams(location.search).has('mini'))return <div className="mini-window"><Player state={activeState} send={send}/></div>;
  return <div className="app">
    <LocalPlayerEngine state={localState} enabled={local} ended={()=>send('ended')} progress={syncLocalProgress} playback={setLocalPlayback} fail={failLocalPlayback}/>
    <aside><div className="brand"><div className="brandmark"><img src={inazumaLogo} alt="Inazuma Music"/></div></div>
      <nav>{navTabs.map(t=><button key={t.id} className={tab===t.id?'active':''} onClick={()=>setTab(t.id)}><t.icon/> {t.label}{t.id==='queue'&&state.queue.length>0?<i>{state.queue.length}</i>:null}</button>)}</nav>
      <div className="aside-bottom"><div className={`connection ${state.connected?'ok':''}`}><span/><div><b>{state.connected?'Connecté':'Déconnecté'}</b><small>{demo?'Mode démonstration':config.wsUrl.replace('ws://','')}</small></div></div><ProfileMenu userName={state.userName||config.discordUserName} userAvatar={state.userAvatar||config.discordAvatar} settings={()=>setTab('settings')} notice={setNotice}/><div className="version-label">Version 2.1.4 <span>OFFICIEL</span></div></div>
    </aside>
    <main><header><div><p>{tabs.find(x=>x.id===tab)?.label}</p><h1>{tab==='home'?((state.userName||config.discordUserName)?`Bonsoir, ${state.userName||config.discordUserName}.`:'Bonsoir.'):tab==='search'?'Trouve le prochain son.':tab==='playlists'?'Tes playlists':tab==='queue'?'File d’attente':tab==='history'?'Dernières écoutes':'Configuration'}</h1></div><div className="header-actions"><OutputPicker value={config.playbackTarget} change={changeOutput}/><ServerPicker state={state} select={id=>send('select_guild',id)}/></div></header>
      <section className="content">{tab==='home'&&<HomePage state={activeState} send={send} go={setTab}/>} {tab==='search'&&<SearchPage send={send} playlists={library.playlists} addToPlaylist={addToPlaylist} library={library} save={saveLibrary}/>} {tab==='lyrics'&&<LyricsPage state={activeState}/>} {tab==='favorites'&&<FavoritesPage library={library} save={saveLibrary} send={send}/>} {tab==='playlists'&&<PlaylistsPage playlists={library.playlists} save={playlists=>saveLibrary({...library,playlists})} send={send}/>} {tab==='queue'&&<QueuePage state={activeState} send={send}/>} {tab==='history'&&<HistoryPage history={library.history} favorites={library.favorites} send={send} clear={()=>saveLibrary({...library,history:[]})} favorite={track=>saveLibrary({...library,favorites:library.favorites.some(item=>item.id===track.id)?library.favorites.filter(item=>item.id!==track.id):[track,...library.favorites]})}/>} {tab==='settings'&&<SettingsWorkspace config={config} state={state} save={async c=>{setConfig(await window.newaa.setConfig(c));setNotice('Configuration enregistrée.')}} logs={logs} notice={setNotice}/>}</section>
    </main>
    <Player state={activeState} send={send}/>{notice&&<div className="toast">{notice}</div>}
  </div>
}

function OutputPicker({value,change}:{value:'local'|'discord';change:(value:'local'|'discord')=>void}){
  return <div className="output-picker" aria-label="Sortie audio"><button className={value==='local'?'active':''} onClick={()=>change('local')} title="Écouter sur cet ordinateur"><Headphones/> Application</button><button className={value==='discord'?'active':''} onClick={()=>change('discord')} title="Écouter dans le salon vocal"><Radio/> Discord</button></div>
}

function LocalPlayerEngine({state,enabled,ended,progress,playback,fail}:{state:PlayerState;enabled:boolean;ended:()=>void;progress:(elapsed:number,duration:number)=>void;playback:(playing:boolean)=>void;fail:(message:string)=>void}){
  const host=useRef<HTMLDivElement|null>(null);const audio=useRef<HTMLAudioElement|null>(null);const player=useRef<YouTubePlayer|null>(null);const ready=useRef(false);
  const stateRef=useRef(state);const endedRef=useRef(ended);const progressRef=useRef(progress);const playbackRef=useRef(playback);const failRef=useRef(fail);
  stateRef.current=state;endedRef.current=ended;progressRef.current=progress;playbackRef.current=playback;failRef.current=fail;
  const mp3=state.current?.source==='mp3'&&Boolean(state.current.url);const youtube=enabled&&state.current&&!mp3?state.current:null;
  const playMp3=()=>audio.current?.play().catch(error=>{if((error as Error)?.name!=='AbortError')failRef.current(`Lecture MP3 impossible : ${(error as Error)?.message||'erreur inconnue'}.`)});
  const finish=()=>{const current=stateRef.current;if(current.loop==='track'){progressRef.current(0,seconds(current.current?.duration||''));if(audio.current){audio.current.currentTime=0;void playMp3()}else if(player.current){player.current.seekTo(0,true);player.current.playVideo()}return}endedRef.current()};

  useEffect(()=>{const wrapper=host.current;if(!youtube||!wrapper)return;let cancelled=false;ready.current=false;const mount=document.createElement('div');mount.className='local-youtube-mount';wrapper.replaceChildren(mount);loadYouTubeIframeApi().then(api=>{if(cancelled||!mount.isConnected)return;const instance=new api.Player(mount,{width:200,height:200,videoId:youtube.id,playerVars:{autoplay:stateRef.current.playing?1:0,controls:0,disablekb:1,fs:0,playsinline:1,rel:0,widget_referrer:YOUTUBE_CLIENT_IDENTITY},events:{onReady:event=>{if(cancelled)return;ready.current=true;event.target.setVolume(stateRef.current.volume);if(stateRef.current.volume>0)event.target.unMute();else event.target.mute();if(stateRef.current.playing)event.target.playVideo();else event.target.pauseVideo()},onStateChange:event=>{if(cancelled)return;if(event.data===api.PlayerState.PLAYING)playbackRef.current(true);else if(event.data===api.PlayerState.PAUSED)playbackRef.current(false);else if(event.data===api.PlayerState.ENDED)finish()},onError:event=>{if(!cancelled)failRef.current(youtubePlaybackError(event.data))},onAutoplayBlocked:()=>{if(!cancelled)failRef.current('YouTube a bloqué le démarrage automatique. Appuie sur Lecture pour réessayer.')}}});player.current=instance}).catch(error=>{if(!cancelled)failRef.current(error instanceof Error?error.message:String(error))});return()=>{cancelled=true;ready.current=false;const instance=player.current;player.current=null;try{instance?.destroy()}catch{}try{wrapper.replaceChildren()}catch{}}},[enabled,state.current?.id,mp3]);
  useEffect(()=>{if(!youtube)return;const timer=window.setInterval(()=>{const instance=player.current;if(!ready.current||!instance)return;try{progressRef.current(instance.getCurrentTime(),instance.getDuration())}catch{}},500);return()=>window.clearInterval(timer)},[youtube?.id]);
  useEffect(()=>{if(!enabled)return;if(mp3&&audio.current){audio.current.volume=Math.max(0,Math.min(1,state.volume/100));if(state.playing)void playMp3();else audio.current.pause()}else if(ready.current&&player.current){player.current.setVolume(state.volume);if(state.volume>0)player.current.unMute();else player.current.mute();if(state.playing)player.current.playVideo();else player.current.pauseVideo()}},[enabled,state.playing,state.volume,state.current?.id,mp3]);
  useEffect(()=>{const command=(event:Event)=>{if(!enabled)return;const detail=(event as CustomEvent<{action:string;payload?:unknown}>).detail;if(detail.action==='seek'){const value=Math.max(0,Number(detail.payload)||0);if(mp3&&audio.current)audio.current.currentTime=value;else if(ready.current)player.current?.seekTo(value,true)}if(detail.action==='stop'){if(audio.current){audio.current.pause();audio.current.currentTime=0}try{player.current?.stopVideo()}catch{}}};window.addEventListener('inazuma-local-command',command);return()=>window.removeEventListener('inazuma-local-command',command)},[enabled,mp3,state.current?.id]);
  if(!enabled||!state.current)return null;
  if(mp3)return <audio ref={audio} className="local-audio-engine" src={state.current.url} preload="auto" onPlaying={()=>playbackRef.current(true)} onPause={()=>playbackRef.current(false)} onTimeUpdate={event=>progressRef.current(event.currentTarget.currentTime,event.currentTarget.duration)} onEnded={finish} onError={event=>{const code=event.currentTarget.error?.code||0;const reason=code===2?'erreur réseau':code===3?'fichier illisible':code===4?'format non pris en charge':'source indisponible';failRef.current(`Lecture MP3 impossible : ${reason}.`)}}/>;
  return <section className="local-youtube-engine" aria-label="Lecteur YouTube local"><div className="local-youtube-title"><span><i/> LECTURE LOCALE</span><b>YouTube</b></div><div ref={host} className="local-youtube-frame"/></section>;
}

function ProfileMenu({userName,userAvatar,settings,notice}:{userName:string;userAvatar:string;settings:()=>void;notice:(message:string)=>void}){
  const[open,setOpen]=useState(false);const wrap=useRef<HTMLDivElement|null>(null);
  useEffect(()=>{const close=(event:MouseEvent)=>{if(!wrap.current?.contains(event.target as Node))setOpen(false)};const escape=(event:KeyboardEvent)=>{if(event.key==='Escape')setOpen(false)};document.addEventListener('mousedown',close);document.addEventListener('keydown',escape);return()=>{document.removeEventListener('mousedown',close);document.removeEventListener('keydown',escape)}},[]);
  return <div className="profile-wrap" ref={wrap}>{open&&<div className="profile-menu" role="menu"><button onClick={()=>{settings();setOpen(false)}}><Settings/><span><b>Paramètres</b><small>Configurer le bot</small></span></button><button onClick={async()=>{const info=await window.newaa.getAppInfo();notice(`${info.name} • version ${info.version}`);setOpen(false)}}><Info/><span><b>À propos</b><small>Version de l’application</small></span></button><button className="danger" onClick={()=>window.newaa.quitApp()}><LogOut/><span><b>Quitter</b><small>Fermer Inazuma Music</small></span></button></div>}<button className="profile" onClick={()=>setOpen(v=>!v)} aria-expanded={open} aria-haspopup="menu"><div>{userAvatar?<img src={userAvatar} alt=""/>:<span>{userName.slice(0,1).toUpperCase()||'?'}</span>}</div><span><b>{userName||'Utilisateur'}</b><small>Compte Discord</small></span><ChevronDown className={open?'rotated':''}/></button></div>
}

function ServerPicker({state,select}:{state:PlayerState;select:(id:string)=>void}){const[open,setOpen]=useState(false);return <div className="server-wrap"><button className="server" onClick={()=>setOpen(v=>!v)} aria-expanded={open}><Radio/><span><small>SERVEUR ACTIF</small><b>{state.guildName}</b></span><ChevronDown className={open?'rotated':''}/></button>{open&&<div className="server-menu">{state.guilds.length?state.guilds.map(g=><button key={g.id} className={g.id===state.guildId?'selected':''} onClick={()=>{select(g.id);setOpen(false)}}><span>{g.icon?<img src={g.icon}/>:g.name.slice(0,1).toUpperCase()}</span><div><b>{g.name}</b><small>{g.id===state.guildId?'Serveur actif':'Choisir ce serveur'}</small></div>{g.id===state.guildId&&<i/>}</button>):<p>Le bot n’est présent sur aucun serveur.</p>}</div>}</div>}

function HomePage({state,send,go}:{state:PlayerState;send:(a:string,p?:unknown)=>void;go:(x:string)=>void}){return <>
  {state.voiceMembers.length>0&&<div className="voice-members"><span>AVEC TOI DANS LE VOCAL</span><div>{state.voiceMembers.map(member=><div className="voice-member" key={member.id} title={member.name}>{member.avatar?<img src={member.avatar} alt=""/>:<b>{member.name.slice(0,1).toUpperCase()}</b>}<i className={member.bot?'bot':''}/></div>)}</div><small>{state.voiceMembers.length} membre{state.voiceMembers.length!==1?'s':''}</small></div>}
  <div className="status-grid"><article><div className="status-icon purple"><Bot/></div><div><small>ÉTAT DU BOT</small><h3>{state.botOnline?'En ligne':'Hors ligne'}</h3><p><span className={state.botOnline?'dot':''}/> {state.connected?'Latence temps réel active':'Connexion indisponible'}</p></div></article><article><div className="status-icon pink"><Wifi/></div><div><small>SALON VOCAL</small><h3>{state.voiceChannel}</h3><p>{state.botOnline?'Connecté et prêt à jouer':'Le bot doit rejoindre un salon'}</p></div></article><article><div className="status-icon blue"><ListMusic/></div><div><small>FILE D’ATTENTE</small><h3>{state.queue.length} titre{state.queue.length!==1?'s':''}</h3><p>{state.queue.length?`À suivre : ${state.queue[0].title.slice(0,25)}`:'Ajoute de la musique'}</p></div></article></div>
  <div className="home-grid"><article className="now-card"><div className="eyebrow"><span>LECTURE EN COURS</span><Activity/></div>{state.current?<><img src={state.current.thumbnail}/><div className="now-info"><h2>{state.current.title}</h2><p>{state.current.channel}</p><div className="wave">{Array.from({length:34}).map((_,i)=><i key={i} style={{height:`${12+(i*17)%38}px`}}/>)}</div><div className="hero-controls"><button onClick={()=>send('previous')} title="Morceau précédent"><SkipBack/></button><button onClick={()=>send('toggle_pause')} className="hero-play">{state.playing?<Pause/>:<Play/>}</button><button onClick={()=>send('skip')} title="Morceau suivant"><SkipForward/></button><button onClick={()=>send('stop')}><Square/></button></div></div></>:<div className="empty big"><Music2/><h3>Rien ne joue</h3><button onClick={()=>go('search')}>Rechercher une vidéo</button></div>}</article>
    <article className="quick"><div className="section-title"><div><small>CONTRÔLE RAPIDE</small><h2>À suivre</h2></div><button onClick={()=>go('queue')}>Voir la queue</button></div>{state.queue.slice(0,4).map((t,i)=><TrackRow key={t.id+i} t={t} index={i+1} action={<button onClick={()=>send('remove_queue',i)}><Trash2/></button>}/>)}{!state.queue.length&&<div className="empty"><ListMusic/><p>La file est vide.</p></div>}<button className="search-cta" onClick={()=>go('search')}><Plus/> Ajouter de la musique</button></article></div></>}

function SearchPage({send,playlists,addToPlaylist,library,save}:{send:(a:string,p?:unknown)=>void;playlists:Playlist[];addToPlaylist:(id:string,t:Track)=>void;library:Library;save:(x:Library)=>void}){const[q,setQ]=useState('');const[items,setItems]=useState<Track[]>([]);const[selected,setSelected]=useState<Track|null>(null);const[loading,setLoading]=useState(false);const[error,setError]=useState('');const[token,setToken]=useState('');const[focus,setFocus]=useState(false);
 const known=[...library.searchHistory,...library.history.map(x=>x.title),...library.favorites.map(x=>x.title)];const suggestions=[...new Set(known)].filter(x=>!q.trim()||x.toLowerCase().includes(q.toLowerCase())).slice(0,6);const favorite=(t:Track)=>library.favorites.some(x=>x.id===t.id);const toggleFavorite=(t:Track)=>save({...library,favorites:favorite(t)?library.favorites.filter(x=>x.id!==t.id):[t,...library.favorites]});
 const search=async(more=false)=>{if(!q.trim())return;setFocus(false);setLoading(true);setError('');if(!more)save({...library,searchHistory:[q.trim(),...library.searchHistory.filter(x=>x.toLowerCase()!==q.trim().toLowerCase())].slice(0,12)});try{const r=await window.newaa.searchYouTube(q,more?token:'');const clean=r.items.map(x=>({...x,title:decode(x.title),channel:decode(x.channel),duration:isoDuration(x.duration),source:'youtube' as const}));setItems(v=>more?[...v,...clean]:clean);setToken(r.nextPageToken)}catch(e){setError(e instanceof Error?e.message:String(e))}finally{setLoading(false)}};
 const addLink=()=>{try{const url=new URL(q.trim());if(url.protocol!=='https:'||!url.pathname.toLowerCase().endsWith('.mp3'))throw new Error();const title=decodeURIComponent(url.pathname.split('/').pop()||'Musique MP3').replace(/\.mp3$/i,'');setSelected({id:`mp3-${Date.now()}`,title,channel:url.hostname,thumbnail:'',duration:'MP3',source:'mp3',url:url.href})}catch{setError('Colle un lien HTTPS direct qui se termine par .mp3.')}};
 return <><div className="search-wrap"><form className="searchbar" onSubmit={e=>{e.preventDefault();search()}}><Search/><input value={q} onFocus={()=>setFocus(true)} onChange={e=>{setQ(e.target.value);setFocus(true)}} placeholder="Titre, artiste, lien YouTube ou lien MP3…"/><button>Rechercher</button></form>{focus&&suggestions.length>0&&<div className="search-assist"><small>HISTORIQUE ET SUGGESTIONS</small>{suggestions.map(x=><button key={x} onMouseDown={e=>e.preventDefault()} onClick={()=>{setQ(x);setFocus(false)}}><Clock3/>{x}</button>)}</div>}</div><div className="mp3-actions"><button onClick={addLink}><Plus/> Ajouter le lien MP3</button><button onClick={async()=>{setError('');try{const track=await window.newaa.selectAndUploadMp3();if(track)setSelected(track)}catch(e){setError(e instanceof Error?e.message:String(e))}}}><Music2/> Envoyer un fichier MP3</button></div>{error&&<div className="error">{error}</div>}
 {!items.length&&!loading?<div className="search-empty"><div><Search/></div><h2>Qu’est-ce qu’on écoute ?</h2><p>Recherche YouTube, lien MP3 ou fichier joint : tout est au même endroit.</p><div className="suggestions">{['lofi hip hop','musique gaming','mix années 2000'].map(x=><button key={x} onClick={()=>setQ(x)}>{x}</button>)}</div></div>:<div className="video-grid">{items.map(t=><div className={`video-card ${favorite(t)?'favorite':''}`} key={t.id}><button className="video" onClick={()=>setSelected(t)}><div><img src={t.thumbnail}/><span>{t.duration}</span><i><Play/></i></div><h3>{t.title}</h3><p>{t.channel}</p></button><FavoriteButton className="result-heart" active={favorite(t)} onClick={()=>toggleFavorite(t)}/></div>)}</div>}{loading&&<div className="spinner"/>}{token&&!loading&&<button className="load-more" onClick={()=>search(true)}>Afficher plus</button>}
 {selected&&<div className="modalback" onClick={()=>setSelected(null)}><div className="modal" onClick={e=>e.stopPropagation()}>{selected.thumbnail?<img src={selected.thumbnail}/>:<div className="mp3-cover"><Music2/></div>}<small>{selected.source==='mp3'?'MP3 SÉLECTIONNÉ':'VIDÉO SÉLECTIONNÉE'}</small><h2>{selected.title}</h2><p>{selected.channel} · {selected.duration}</p><div><button onClick={()=>{send('play_now',selected);setSelected(null)}} className="primary"><Play/> Lire maintenant</button><button onClick={()=>{send('play_next',selected);setSelected(null)}}><Zap/> Lire ensuite</button><button onClick={()=>{send('enqueue',selected);setSelected(null)}}><Plus/> Ajouter à la file</button><FavoriteButton className="modal-favorite" active={favorite(selected)} onClick={()=>toggleFavorite(selected)} label/></div>{playlists.length?<label className="playlist-select">Ajouter à une playlist<select defaultValue="" onChange={e=>{if(e.target.value){addToPlaylist(e.target.value,selected);setSelected(null)}}}><option value="" disabled>Choisir…</option>{playlists.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label>:<p className="playlist-tip">Crée d’abord une playlist dans l’onglet Playlists.</p>}</div></div>}</>}

function QueuePage({state,send}:{state:PlayerState;send:(a:string,p?:unknown)=>void}){const[drag,setDrag]=useState<number|null>(null);const drop=(to:number)=>{if(drag===null||drag===to)return;const q=[...state.queue];const[x]=q.splice(drag,1);q.splice(to,0,x);send('reorder_queue',q);setDrag(null)};return <article className="panel"><div className="section-title"><div><small>PROCHAINS TITRES</small><h2>{state.queue.length} musique{state.queue.length!==1?'s':''}</h2></div>{state.queue.length>0&&<button onClick={()=>send('clear_queue')}><Trash2/> Vider la file</button>}</div><div className="queue-head"><span>#</span><span>TITRE</span><span>DEMANDÉ PAR</span><span>DURÉE</span><span/></div>{state.queue.map((t,i)=><div className="queue-row" draggable onDragStart={()=>setDrag(i)} onDragOver={e=>e.preventDefault()} onDrop={()=>drop(i)} key={`${t.id}-${i}`}><GripVertical/><b>{i+1}</b><img src={t.thumbnail}/><div><strong>{t.title}</strong><small>{t.channel}</small></div><span>{t.requestedBy||'Desktop'}</span><span>{t.duration}</span><button onClick={()=>send('remove_queue',i)}><Trash2/></button></div>)}{!state.queue.length&&<div className="empty big"><ListMusic/><h3>Ta file est vide</h3><p>Ajoute des vidéos depuis l’onglet Recherche.</p></div>}</article>}
function FavoriteButton({active,onClick,className='',label=false}:{active:boolean;onClick:()=>void;className?:string;label?:boolean}){const[pulse,setPulse]=useState(false);return <button className={`${className} favorite-button ${active?'fav-active':''} ${pulse?'heart-pop':''}`} title={active?'Retirer des favoris':'Ajouter aux favoris'} onClick={()=>{setPulse(false);requestAnimationFrame(()=>{setPulse(true);window.setTimeout(()=>setPulse(false),520)});onClick()}}><Heart fill={active?'currentColor':'none'}/>{label?' Favori':null}</button>}

function HistoryPage({history,favorites,send,clear,favorite}:{history:Track[];favorites:Track[];send:(a:string,p?:unknown)=>void;clear:()=>void;favorite:(track:Track)=>void}){const liked=(track:Track)=>favorites.some(item=>item.id===track.id);return <article className="panel"><div className="section-title"><div><small>HISTORIQUE LOCAL PERSISTANT</small><h2>Récemment écouté</h2></div>{history.length>0&&<button onClick={clear}><Trash2/> Effacer</button>}</div>{history.map((t,i)=><TrackRow key={t.id+i} t={t} index={i+1} action={<div className="track-actions"><FavoriteButton active={liked(t)} onClick={()=>favorite(t)}/><button className="replay" onClick={()=>send('play_now',t)}><RotateCcw/> Rejouer</button></div>}/>)}{!history.length&&<div className="empty big"><Clock3/><h3>Aucune écoute récente</h3><p>Chaque morceau passé ou remplacé sera conservé ici.</p></div>}</article>}

function FavoritesPage({library,save,send}:{library:Library;save:(library:Library)=>void;send:(a:string,p?:unknown)=>void}){const remove=(id:string)=>save({...library,favorites:library.favorites.filter(track=>track.id!==id),pinned:library.pinned.filter(track=>track.id!==id)});const togglePin=(track:Track)=>save({...library,pinned:library.pinned.some(item=>item.id===track.id)?library.pinned.filter(item=>item.id!==track.id):[track,...library.pinned.filter(item=>item.id!==track.id)]});return <article className="panel"><div className="section-title"><div><small>BIBLIOTHÈQUE PERSONNELLE</small><h2>Favoris et morceaux épinglés</h2></div><span className="library-stat">{Math.floor(library.stats.totalSeconds/60)} min · {library.stats.tracksPlayed} écoutes</span></div>{library.pinned.length>0&&<div className="pinned-strip">{library.pinned.map(track=><button key={track.id} onClick={()=>send('play_now',track)}><img src={track.thumbnail}/><span><small>ÉPINGLÉ</small><b>{track.title}</b></span><Play/></button>)}</div>}{library.favorites.map((track,index)=><TrackRow key={track.id} t={track} index={index+1} action={<div className="track-actions"><button className={library.pinned.some(item=>item.id===track.id)?'pinned':''} onClick={()=>togglePin(track)}><Pin/></button><button onClick={()=>send('play_now',track)}><Play/></button><button onClick={()=>remove(track.id)}><Trash2/></button></div>}/>)}{!library.favorites.length&&<div className="empty big"><Heart/><h3>Aucun favori</h3><p>Ajoute un morceau depuis ton historique d’écoute.</p></div>}</article>}

function PlaylistsPage({playlists,save,send}:{playlists:Playlist[];save:(p:Playlist[])=>void;send:(a:string,p?:unknown)=>void}){const[name,setName]=useState('');const[selected,setSelected]=useState(playlists[0]?.id||'');const[community,setCommunity]=useState<Playlist[]>([]);const[query,setQuery]=useState('');const[busy,setBusy]=useState(false);const active=playlists.find(p=>p.id===selected)||playlists[0];const load=async(q='')=>{setBusy(true);try{setCommunity(await window.newaa.getPublicPlaylists(q))}finally{setBusy(false)}};useEffect(()=>{load()},[]);const create=()=>{const n=name.trim();if(!n)return;const p:Playlist={id:rid(),name:n,createdAt:Date.now(),tracks:[],visibility:'private',shareKey:`${rid()}${rid()}`};save([...playlists,p]);setSelected(p.id);setName('')};const update=async(p:Playlist)=>{save(playlists.map(x=>x.id===p.id?p:x));if(p.visibility==='public')await window.newaa.publishPlaylist(p);else if(p.shareKey)await window.newaa.unpublishPlaylist(p.id,p.shareKey);load(query)};const removeTrack=(id:string)=>active&&update({...active,tracks:active.tracks.filter(t=>t.id!==id)});const remove=async()=>{if(!active)return;if(active.visibility==='public'&&active.shareKey)await window.newaa.unpublishPlaylist(active.id,active.shareKey);save(playlists.filter(p=>p.id!==active.id));setSelected('');load(query)};const importPlaylist=(p:Playlist)=>{const copy={...p,id:rid(),name:`${p.name} — ${p.ownerName}`,createdAt:Date.now(),visibility:'private' as const,shareKey:`${rid()}${rid()}`};save([...playlists,copy]);setSelected(copy.id)};return <div className="playlist-page"><div className="playlists-layout"><article className="panel playlist-sidebar"><div className="section-title"><div><small>TA BIBLIOTHÈQUE</small><h2>Mes playlists</h2></div></div><form onSubmit={e=>{e.preventDefault();create()}}><input value={name} onChange={e=>setName(e.target.value)} placeholder="Nom de la playlist"/><button className="primary"><Plus/> Créer</button></form>{playlists.map(p=><button className={active?.id===p.id?'active':''} key={p.id} onClick={()=>setSelected(p.id)}><Music2/><span><b>{p.name}</b><small>{p.visibility==='public'?'Publique':'Privée'} · {p.tracks.length} titre{p.tracks.length!==1?'s':''}</small></span></button>)}</article><article className="panel playlist-detail">{active?<><div className="section-title"><div><small>PLAYLIST {active.visibility==='public'?'PUBLIQUE':'PRIVÉE'}</small><h2>{active.name}</h2></div><div className="playlist-actions"><button className={`privacy ${active.visibility==='public'?'public':''}`} onClick={()=>update({...active,visibility:active.visibility==='public'?'private':'public',shareKey:active.shareKey||`${rid()}${rid()}`})}>{active.visibility==='public'?'Rendre privée':'Rendre publique'}</button><button onClick={()=>active.tracks.forEach(t=>send('enqueue',t))}><Plus/> File</button><button onClick={()=>{active.tracks.forEach((t,i)=>send(i===0?'play_now':'enqueue',t))}}><Play/> Tout lire</button><button onClick={remove}><Trash2/></button></div></div>{active.tracks.map((t,i)=><TrackRow key={t.id+i} t={t} index={i+1} action={<div className="track-actions"><button onClick={()=>send('play_now',t)}><Play/></button><button onClick={()=>removeTrack(t.id)}><Trash2/></button></div>}/>)}{!active.tracks.length&&<div className="empty big"><Music2/><h3>Playlist vide</h3><p>Ajoute des morceaux depuis la recherche.</p></div>}</>:<div className="empty big"><Music2/><h3>Crée ta première playlist</h3></div>}</article></div><article className="panel community"><div className="section-title"><div><small>COMMUNAUTÉ</small><h2>Playlists publiques</h2></div><form onSubmit={e=>{e.preventDefault();load(query)}}><Search/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Rechercher une playlist ou un créateur"/><button>Rechercher</button></form></div><div className="community-grid">{community.map(p=><div className="community-card" key={p.id}><div>{p.ownerAvatar?<img src={p.ownerAvatar}/>:<Music2/>}<span><small>PAR {p.ownerName||'UTILISATEUR'}</small><b>{p.name}</b></span></div><p>{p.tracks.length} titre{p.tracks.length!==1?'s':''}</p><div><button onClick={()=>p.tracks.forEach((t,i)=>send(i===0?'play_now':'enqueue',t))}><Play/> Lire</button><button onClick={()=>importPlaylist(p)}><Plus/> Ajouter à mes playlists</button></div></div>)}{!community.length&&!busy&&<div className="empty"><Music2/><p>Aucune playlist publique trouvée.</p></div>}{busy&&<div className="spinner"/>}</div></article></div>}
function TrackRow({t,index,action}:{t:Track;index:number;action:ReactNode}){return <div className="track-row"><b>{String(index).padStart(2,'0')}</b><img src={t.thumbnail}/><div><strong>{t.title}</strong><small>{t.channel}</small></div><span>{t.duration}</span><div className="track-actions"><button onClick={()=>enqueueTrackRow?.(t)} title="Ajouter ce morceau à la file"><Plus/></button>{action}</div></div>}

type LyricLine={time:number;text:string};
function parseLyrics(value:string):LyricLine[]{const lines:LyricLine[]=[];for(const row of value.split(/\r?\n/)){const matches=[...row.matchAll(/\[(\d{1,2}):(\d{2}(?:\.\d{1,3})?)\]/g)];const text=row.replace(/\[[^\]]+\]/g,'').trim();for(const match of matches)lines.push({time:Number(match[1])*60+Number(match[2]),text:text||'♪'})}return lines.sort((a,b)=>a.time-b.time)}
function LyricsPage({state}:{state:PlayerState}){const[result,setResult]=useState<{trackName:string;artistName:string;syncedLyrics:string;plainLyrics:string;instrumental:boolean}|null>(null);const[loading,setLoading]=useState(false);const[error,setError]=useState('');const[retry,setRetry]=useState(0);const[title,setTitle]=useState('');const[artist,setArtist]=useState('');const activeRef=useRef<HTMLParagraphElement|null>(null);useEffect(()=>{if(state.current){setTitle(state.current.title);setArtist(state.current.channel)}},[state.current?.id]);useEffect(()=>{let alive=true;if(!state.current){setResult(null);return}setLoading(true);setError('');window.newaa.searchLyrics(title||state.current.title,artist||state.current.channel,seconds(state.current.duration),retry>0).then(value=>{if(alive)setResult(value)}).catch(reason=>{if(alive)setError(reason instanceof Error?reason.message:String(reason))}).finally(()=>{if(alive)setLoading(false)});return()=>{alive=false}},[state.current?.id,retry]);const lines=parseLyrics(result?.syncedLyrics||'');let active=-1;for(let index=0;index<lines.length;index++){if(lines[index].time<=state.elapsed+.2)active=index;else break}useEffect(()=>{activeRef.current?.scrollIntoView({behavior:'smooth',block:'center'})},[active]);if(!state.current)return <article className="panel lyrics-page"><div className="empty big"><Mic2/><h3>Aucune musique en cours</h3><p>Lance un morceau pour afficher ses paroles.</p></div></article>;return <article className="panel lyrics-page"><div className="lyrics-head">{state.current.thumbnail?<img src={state.current.thumbnail}/>:<div className="lyrics-art"><Music2/></div>}<div><small>PAROLES {lines.length?'SYNCHRONISÉES':'DU MORCEAU'}</small><h2>{result?.trackName||state.current.title}</h2><p>{result?.artistName||state.current.channel}</p></div><span>{loading?'Recherche…':lines.length?'Synchronisées':'Texte intégral'}</span></div><form className="sync-repair" onSubmit={e=>{e.preventDefault();setRetry(x=>x+1)}}><input value={title} onChange={e=>setTitle(e.target.value)} placeholder="Titre exact"/><input value={artist} onChange={e=>setArtist(e.target.value)} placeholder="Artiste exact"/><button disabled={loading}><RotateCcw/> Réparer la synchro</button></form>{loading?<div className="spinner"/>:error?<div className="error">{error}</div>:result?.instrumental?<div className="empty big"><Music2/><h3>Morceau instrumental</h3></div>:lines.length?<div className="synced-lyrics">{lines.map((line,index)=><p key={`${line.time}-${index}`} ref={index===active?activeRef:null} className={index===active?'active':index<active?'past':''}>{line.text}</p>)}</div>:result?.plainLyrics?<div className="plain-lyrics">{result.plainLyrics}</div>:<div className="empty big"><Mic2/><h3>Paroles introuvables</h3><p>Corrige le titre ou l’artiste puis utilise « Réparer la synchro ».</p></div>}</article>}

function SettingsWorkspace({config,state,save,logs,notice}:{config:Config;state:PlayerState;save:(c:Config)=>void;logs:string;notice:(s:string)=>void}){
  const[c,setC]=useState(config);
  useEffect(()=>setC(config),[config]);
  return <div className="settings-workspace">
    <SettingsPage config={config} state={state} save={save} logs={logs} notice={notice}/>
    <article className="panel presence-panel"><div className="section-title"><div><small>DISCORD</small><h2>Rich Presence</h2></div><div className={`pill ${c.presenceEnabled?'':'demo'}`}>{c.presenceEnabled?'Active':'Désactivée'}</div></div>
      <div className="presence-preview"><img src={inazumaLogo} alt="Inazuma Music"/><div><small>INAZUMA MUSIC</small><b>{c.presenceShowTrack&&state.current?state.current.title:(c.presenceDetails||'En écoute sur Inazuma Music')}</b><span>{c.presenceShowTrack&&state.current?`${state.playing?'En lecture':'En pause'} • ${state.current.channel}`:(c.presenceState||'Version 2.1.4 • OFFICIEL')}</span></div></div>
      <label className="toggle"><span><b>Afficher la Rich Presence</b><small>Logo Inazuma et boutons configurables sur ton profil Discord.</small></span><input type="checkbox" checked={c.presenceEnabled} onChange={e=>setC({...c,presenceEnabled:e.target.checked})}/><i/></label>
      <label className="field"><span>Type d’activité affiché par Discord</span><select value={c.presenceType} onChange={e=>setC({...c,presenceType:e.target.value as Config['presenceType']})}><option value="listening">Écoute — recommandé pour Inazuma Music</option><option value="playing">Joue à</option><option value="watching">Regarde</option><option value="competing">Participe à</option></select></label>
      <label className="toggle"><span><b>Afficher automatiquement le morceau</b><small>Titre, artiste et état lecture/pause remplacent tes textes pendant la lecture.</small></span><input type="checkbox" checked={c.presenceShowTrack} onChange={e=>setC({...c,presenceShowTrack:e.target.checked})}/><i/></label>
      <div className="presence-fields"><Field label="Texte principal personnalisé" value={c.presenceDetails} onChange={v=>setC({...c,presenceDetails:v})} placeholder="En écoute sur Inazuma Music"/><Field label="Sous-texte personnalisé" value={c.presenceState} onChange={v=>setC({...c,presenceState:v})} placeholder="Version 2.1.4 • OFFICIEL"/></div>
      <div className="presence-fields"><label className="field"><span>Image principale</span><select value={c.presenceLargeImageKey} onChange={e=>setC({...c,presenceLargeImageKey:e.target.value})}><option value="inazuma_music_logo">Logo Inazuma Music</option></select></label><Field label="Texte au survol du logo" value={c.presenceLargeImageText} onChange={v=>setC({...c,presenceLargeImageText:v})} placeholder="Inazuma Music"/></div>
      <div className="presence-fields"><Field label="Texte du lien" value={c.presenceLinkLabel} onChange={v=>setC({...c,presenceLinkLabel:v})} placeholder="Site / Discord"/><Field label="URL du lien" value={c.presenceLinkUrl} onChange={v=>setC({...c,presenceLinkUrl:v})} placeholder="https://..."/></div>
      <div className="presence-fields"><Field label="Texte téléchargement" value={c.presenceDownloadLabel} onChange={v=>setC({...c,presenceDownloadLabel:v})} placeholder="Télécharger Inazuma"/><Field label="URL téléchargement" value={c.presenceDownloadUrl} onChange={v=>setC({...c,presenceDownloadUrl:v})} placeholder="https://..."/></div>
      <div className="presence-options"><label className="toggle"><span><b>Auto-join</b><small>Suit ton changement de vocal.</small></span><input type="checkbox" checked={c.autoJoin} onChange={e=>setC({...c,autoJoin:e.target.checked})}/><i/></label><label className="toggle"><span><b>Auto-leave</b><small>Quitte un vocal devenu vide.</small></span><input type="checkbox" checked={c.autoLeave} onChange={e=>setC({...c,autoLeave:e.target.checked})}/><i/></label></div>
      <div className="presence-fields"><label className="field"><span>Contrôle de session</span><select value={c.controlMode} onChange={e=>setC({...c,controlMode:e.target.value as 'private'|'shared'})}><option value="private">Session privée</option><option value="shared">Contrôle partagé par rôle</option></select></label><Field label="IDs des rôles autorisés" value={c.allowedRoleIds} onChange={v=>setC({...c,allowedRoleIds:v})} placeholder="123..., 456..."/></div>
      <label className="field"><span>Thème</span><select value={c.theme} onChange={e=>setC({...c,theme:e.target.value as Config['theme']})}><option value="inazuma">Inazuma</option><option value="midnight">Midnight</option><option value="ember">Ember</option></select></label>
      <div className="audio-settings"><div className="subhead"><Volume2/><div><b>Traitement audio</b><small>Préréglage, normalisation et transitions douces.</small></div></div><label className="toggle"><span><b>Radio automatique</b><small>En mode Application, lance une musique similaire quand la file est terminée.</small></span><input type="checkbox" checked={c.autoRadio} onChange={e=>setC({...c,autoRadio:e.target.checked})}/><i/></label><div className="presence-fields"><label className="field"><span>Égaliseur</span><select value={c.audioPreset} onChange={e=>setC({...c,audioPreset:e.target.value as Config['audioPreset']})}><option value="normal">Normal</option><option value="bass">Bass Boost</option><option value="vocal">Vocal</option><option value="night">Night</option></select></label><label className="field"><span>Transition (secondes)</span><input type="number" min="0" max="10" value={c.crossfadeSeconds} onChange={e=>setC({...c,crossfadeSeconds:Math.max(0,Math.min(10,Number(e.target.value)))})}/></label></div><label className="toggle"><span><b>Normalisation du volume</b><small>Réduit les écarts brutaux entre les morceaux.</small></span><input type="checkbox" checked={c.normalizeVolume} onChange={e=>setC({...c,normalizeVolume:e.target.checked})}/><i/></label></div>
      <button className="primary save" onClick={()=>save(c)}>Enregistrer la présence</button>
      <button className="mini-toggle" onClick={()=>window.newaa.toggleMiniPlayer()}><Music2/> Ouvrir / fermer le mini-player Windows</button>
    </article>
  </div>
}

function SettingsPage({config,state,save,logs,notice}:{config:Config;state:PlayerState;save:(c:Config)=>void;logs:string;notice:(s:string)=>void}){const[c,setC]=useState(config);const clientId=state.discordClientId||c.discordClientId;const login=async()=>{try{if(!clientId)throw new Error('Le bot doit être connecté pour lancer Discord.');const user=await window.newaa.loginDiscord(clientId);const next={...c,apiToken:user.apiToken,discordClientId:clientId,discordUserId:user.id,discordUserName:user.name,discordAvatar:user.avatar};setC(next);save(next);notice(`Connecté avec Discord : ${user.name}`)}catch(e){notice(e instanceof Error?e.message:String(e))}};const invite=async()=>{try{await window.newaa.inviteBot(clientId)}catch(e){notice(e instanceof Error?e.message:String(e))}};return <div className="settings-grid"><article className="panel"><div className="section-title"><div><small>CONNEXION</small><h2>Bot Discord</h2></div><div className={`pill ${c.demoMode?'demo':''}`}>{c.demoMode?'Démonstration':'Production'}</div></div><label className="toggle"><span><b>Mode démonstration</b><small>Teste toute l’interface sans bot connecté.</small></span><input type="checkbox" checked={c.demoMode} onChange={e=>setC({...c,demoMode:e.target.checked})}/><i/></label><div className="discord-login">{c.discordAvatar?<img src={c.discordAvatar} alt=""/>:<Bot/>}<div><b>{c.discordUserName||'Aucun compte Discord'}</b><small>{c.discordUserName&&c.apiToken?'Compte connecté et prêt':'Connecte-toi pour activer les services Inazuma'}</small></div><div className="discord-actions"><button onClick={invite}><Plus/> Inviter le bot</button><button onClick={login}>{c.discordUserName&&c.apiToken?'Changer':'Se connecter avec Discord'}</button></div></div><p className="setting-help">L’invitation ouvre Discord avec seulement les permissions vocales, messages et commandes nécessaires. La connexion récupère uniquement ton pseudo, ton avatar et ton identifiant public.</p><SelectField label="Serveur préféré" value={c.preferredGuildId} onChange={v=>setC({...c,preferredGuildId:v,preferredTextChannelId:''})} options={state.guilds}/><SelectField label="Salon textuel pour les messages" value={c.preferredTextChannelId} onChange={v=>setC({...c,preferredTextChannelId:v})} options={state.textChannels}/><div className="subhead"><Wifi/><div><b>Salon vocal automatique</b><small>Le bot rejoint uniquement le salon vocal dans lequel tu te trouves.</small></div></div><button className="primary save" onClick={()=>save(c)}>Enregistrer</button></article>
 <article className="panel"><div className="section-title"><div><small>PROCESSUS LOCAL</small><h2>Démarrage du bot</h2></div></div><Field label="Dossier du bot" value={c.botCwd} onChange={v=>setC({...c,botCwd:v})} placeholder="C:\\Bots\\Inazuma-Music"/><Field label="Commande" value={c.botCommand} onChange={v=>setC({...c,botCommand:v})} placeholder="npm start"/><div className="bot-buttons"><button onClick={async()=>notice((await window.newaa.startBot()).message)}><Play/> Démarrer</button><button onClick={async()=>notice((await window.newaa.stopBot()).message)}><Square/> Arrêter</button></div><div className="console"><div><span/><span/><span/><b>Logs du bot</b></div><pre>{logs||'En attente de logs…'}</pre></div></article></div>}
function Field({label,value,onChange,placeholder,secret=false}:{label:string;value:string;onChange:(s:string)=>void;placeholder:string;secret?:boolean}){return <label className="field"><span>{label}</span><input type={secret?'password':'text'} value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder}/></label>}
function SelectField({label,value,onChange,options}:{label:string;value:string;onChange:(s:string)=>void;options:{id:string;name:string}[]}){return <label className="field"><span>{label}</span><select value={value} onChange={e=>onChange(e.target.value)}><option value="">Automatique / aucun</option>{options.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label>}
function clock(total:number){const s=Math.max(0,Math.floor(total||0)),h=Math.floor(s/3600),m=Math.floor((s%3600)/60),r=s%60;return `${h?`${h}:`:''}${h?String(m).padStart(2,'0'):m}:${String(r).padStart(2,'0')}`}
function Player({state,send}:{state:PlayerState;send:(a:string,p?:unknown)=>void}){const nextLoop=state.loop==='off'?'track':state.loop==='track'?'queue':'off';const loopLabel=state.loop==='track'?'Morceau en boucle':state.loop==='queue'?'Playlist en boucle':'Boucle désactivée';return <footer><div className="mini-track">{state.current?<><img src={state.current.thumbnail}/><div><b>{state.current.title}</b><span>{state.current.channel}</span></div></>:<><div className="mini-empty"><Music2/></div><div><b>Aucune lecture</b><span>Choisis une vidéo</span></div></>}</div><div className="footer-center"><div><button className={state.loop!=='off'?'loop-active':''} onClick={()=>send('loop',nextLoop)} title={loopLabel}><Repeat2/>{state.loop==='track'&&<i>1</i>}</button><button onClick={()=>send('previous')} title="Morceau précédent"><SkipBack/></button><button onClick={()=>send('toggle_pause')} className="play">{state.playing?<Pause/>:<Play/>}</button><button onClick={()=>send('skip')} title="Morceau suivant"><SkipForward/></button><button onClick={()=>send('stop')}><Square/></button></div><SeekBar state={state} send={send}/></div><div className="volume"><SleepTimer state={state} send={send}/><Volume2/><input type="range" min="0" max="100" value={state.volume} onChange={e=>send('volume',Number(e.target.value))}/><b>{state.volume}%</b></div></footer>}

function SleepTimer({state,send}:{state:PlayerState;send:(a:string,p?:unknown)=>void}){const[mode,setMode]=useState('off');const[startTrack,setStartTrack]=useState('');useEffect(()=>{if(mode==='track'&&startTrack&&state.current?.id!==startTrack){send('stop');setMode('off')}},[state.current?.id,mode,startTrack]);useEffect(()=>{if(!mode.startsWith('min:'))return;const minutes=Number(mode.slice(4));const timer=window.setTimeout(()=>{send('stop');setMode('off')},minutes*60_000);return()=>window.clearTimeout(timer)},[mode]);return <label className="sleep-timer" title="Sleep timer"><Clock3/><select value={mode} onChange={e=>{setMode(e.target.value);setStartTrack(state.current?.id||'')}}><option value="off">Timer</option><option value="track">Après ce titre</option><option value="min:15">15 min</option><option value="min:30">30 min</option><option value="min:60">60 min</option></select></label>}

function SeekBar({state,send}:{state:PlayerState;send:(a:string,p?:unknown)=>void}){
  const total=seconds(state.current?.duration||'');
  const[preview,setPreview]=useState<number|null>(null);
  useEffect(()=>setPreview(null),[state.current?.id]);
  const value=preview??Math.min(total,state.elapsed);
  const commit=(target:number)=>{setPreview(null);if(state.current&&total>0)send('seek',target)};
  return <div className="timeline"><span>{clock(value)}</span><input className="seekbar" aria-label="Position de lecture" type="range" min="0" max={Math.max(1,total)} step="1" value={value} disabled={!state.current||total<=0} onChange={e=>setPreview(Number(e.target.value))} onPointerUp={e=>commit(Number(e.currentTarget.value))} onKeyUp={e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key))commit(Number(e.currentTarget.value))}}/><span>{state.current?.duration||'0:00'}</span></div>
}
